<script lang="ts">
 import {onMount} from 'svelte';import {goto} from '$app/navigation';import {Button} from '$lib/components/ui/button';import {Bookmark,ThumbsUp,Share2,Flag} from '@lucide/svelte';import {request} from '../api';
 let {video,user,onAccess=()=>{},onOverlayChange=()=>{}}:{video:any;user:any;onAccess?:(actionState:any)=>void;onOverlayChange?:(open:boolean)=>void}=$props();let actionState=$state<any>(null),busy=$state(false),error=$state(''),notice=$state(''),reporting=$state(false),reason=$state('');
 async function load(){try{actionState=await request(`/videos/${video.id}/actions`);onAccess(actionState);}catch(e){error=(e as Error).message;}}
 onMount(()=>{void load();});async function act(kind:'like'|'save'){if(!user){await goto(`/login?returnTo=${encodeURIComponent(location.pathname)}`);return;}busy=true;error='';try{await request(`/videos/${video.id}/${kind}`,{},actionState?.[kind==='like'?'liked':'saved']?'DELETE':'PUT');await load();}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function share(){try{await navigator.clipboard.writeText(`${location.origin}/${video.format==='short'?'shorts':'watch'}/${video.id}`);notice='Link copied.';}catch{notice=`Share this link: ${location.origin}/watch/${video.id}`;}}
 async function report(){busy=true;try{await request(`/videos/${video.id}/report`,{reason});reporting=false;onOverlayChange(false);reason='';notice='Report submitted for review.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<div class="video-actions"><Button variant="outline" size="sm" aria-pressed={!!actionState?.liked} disabled={busy} onclick={()=>act('like')}><ThumbsUp class="size-4"/>{actionState?.likes||0}</Button><Button variant="outline" size="sm" aria-pressed={!!actionState?.saved} disabled={busy} onclick={()=>act('save')}><Bookmark class="size-4"/>{actionState?.saved?'Saved':'Save'}</Button><Button variant="ghost" size="sm" onclick={share}><Share2 class="size-4"/>Share</Button>{#if user}<Button variant="ghost" size="sm" onclick={()=>{reporting=!reporting;onOverlayChange(reporting);}}><Flag class="size-4"/><span class="sr-only">Report video</span></Button>{/if}</div>{#if error}<p role="alert" class="action-message">{error}{#if !actionState}<button class="action-retry" onclick={load}>Try again</button>{/if}</p>{/if}{#if notice}<p role="status" class="action-message">{notice}</p>{/if}{#if reporting}<form class="report-form" onsubmit={e=>{e.preventDefault();void report();}}><label for={`report-${video.id}`}>What should we review?</label><textarea id={`report-${video.id}`} bind:value={reason} minlength={5} maxlength={2000} required></textarea><div><Button disabled={busy} type="submit" size="sm">Submit report</Button><Button size="sm" type="button" variant="ghost" onclick={()=>{reporting=false;onOverlayChange(false);}}>Cancel</Button></div></form>{/if}
<style>.action-retry{text-decoration:underline;text-underline-offset:4px;margin-left:10px}.video-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.action-message{font-size:12px;line-height:1.7;margin-top:12px;color:var(--muted-foreground);overflow-wrap:anywhere}.report-form{display:grid;gap:10px;margin-top:16px;font-size:13px}.report-form textarea{border:1px solid var(--border);border-radius:8px;padding:10px;min-height:90px;background:var(--background);color:var(--foreground)}.report-form>div{display:flex;gap:10px}@media(max-width:600px){.video-actions :global(button){min-height:40px}}</style>
